import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
from torch.nn.modules.utils import _triple

CPP_SRC = r"""
#include <torch/extension.h>
at::Tensor conv3d_forward(at::Tensor input, at::Tensor weight, at::Tensor bias,
                          int64_t stride, int64_t padding, int64_t dilation, int64_t groups);
"""

CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define TILE_X 8
#define TILE_Y 8
#define TILE_Z 8
#define OC_BLOCK 8
#define OC_LANES 4
#define DIRECT_THREADS 256

__global__ void conv3d_fwd_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int Cin, int D, int H, int W,
    int Cout, int K, int Dout, int Hout, int Wout,
    int stride, int pad, int dilation, int groups,
    int has_bias, int use_shared,
    int in_sh_elems, int w_sh_elems,
    int x_tiles, int y_tiles, int z_tiles, int oc_blocks,
    long long total_outputs)
{
    if (!use_shared) {
        long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
        long long step = (long long)gridDim.x * blockDim.x;
        int Cg = Cin / groups;
        int ocpg = Cout / groups;
        for (long long idx = tid; idx < total_outputs; idx += step) {
            long long t = idx;
            int ox = (int)(t % Wout); t /= Wout;
            int oy = (int)(t % Hout); t /= Hout;
            int oz = (int)(t % Dout); t /= Dout;
            int oc = (int)(t % Cout); t /= Cout;
            int n = (int)t;

            int g = oc / ocpg;
            int cbase = g * Cg;
            float acc = has_bias ? bias[oc] : 0.0f;
            for (int c = 0; c < Cg; ++c) {
                int ci = cbase + c;
                for (int kz = 0; kz < K; ++kz) {
                    int iz = oz * stride - pad + kz * dilation;
                    if (iz < 0 || iz >= D) continue;
                    for (int ky = 0; ky < K; ++ky) {
                        int iy = oy * stride - pad + ky * dilation;
                        if (iy < 0 || iy >= H) continue;
                        for (int kx = 0; kx < K; ++kx) {
                            int ix = ox * stride - pad + kx * dilation;
                            if (ix < 0 || ix >= W) continue;
                            long long in_idx = (((long long)(n * Cin + ci) * D + iz) * H + iy) * W + ix;
                            long long w_idx = (((long long)(oc * Cg + c) * K + kz) * K + ky) * K + kx;
                            acc += input[in_idx] * weight[w_idx];
                        }
                    }
                }
            }
            output[idx] = acc;
        }
        return;
    }

    extern __shared__ float smem[];
    float* s_in = smem;
    float* s_w = smem + in_sh_elems;

    int Cg = Cin / groups;
    int ocpg = Cout / groups;

    int xtile = blockIdx.x;
    int ytile = blockIdx.y;
    int zb = blockIdx.z;
    int ztile = zb % z_tiles;
    int tmp = zb / z_tiles;
    int ocb = tmp % oc_blocks;
    int n = tmp / oc_blocks;

    int ox0 = xtile * TILE_X;
    int oy0 = ytile * TILE_Y;
    int oz0 = ztile * TILE_Z;
    int oc0 = ocb * OC_BLOCK;

    int sx = (TILE_X - 1) * stride + (K - 1) * dilation + 1;
    int sy = (TILE_Y - 1) * stride + (K - 1) * dilation + 1;
    int sz = (TILE_Z - 1) * stride + (K - 1) * dilation + 1;

    int in_x0 = ox0 * stride - pad;
    int in_y0 = oy0 * stride - pad;
    int in_z0 = oz0 * stride - pad;

    int g = oc0 / ocpg;
    int cbase = g * Cg;

    int tid = (threadIdx.z * blockDim.y + threadIdx.y) * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y * blockDim.z;

    int in_total = Cg * sz * sy * sx;
    for (int i = tid; i < in_total; i += nthreads) {
        int lox = i % sx;
        int t = i / sx;
        int loy = t % sy;
        t /= sy;
        int loz = t % sz;
        int c = t / sz;

        int ix = in_x0 + lox;
        int iy = in_y0 + loy;
        int iz = in_z0 + loz;
        float v = 0.0f;
        if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
            int ci = cbase + c;
            long long in_idx = (((long long)(n * Cin + ci) * D + iz) * H + iy) * W + ix;
            v = input[in_idx];
        }
        s_in[i] = v;
    }

    int w_total = OC_BLOCK * Cg * K * K * K;
    for (int i = tid; i < w_total; i += nthreads) {
        int kx = i % K;
        int t = i / K;
        int ky = t % K;
        t /= K;
        int kz = t % K;
        t /= K;
        int c = t % Cg;
        int ocl = t / Cg;
        int oc = oc0 + ocl;
        float v = 0.0f;
        if (oc < Cout) {
            long long w_idx = (((long long)(oc * Cg + c) * K + kz) * K + ky) * K + kx;
            v = weight[w_idx];
        }
        s_w[i] = v;
    }
    __syncthreads();

    int lx = threadIdx.x;
    int ly = threadIdx.y;
    int zlane = threadIdx.z;
    int ox = ox0 + lx;
    int oy = oy0 + ly;
    if (ox >= Wout || oy >= Hout) return;
    const int w_oc_stride = Cg * K * K * K;
    for (int lz = zlane; lz < TILE_Z; lz += OC_LANES) {
        int oz = oz0 + lz;
        if (oz >= Dout) continue;
        float acc[OC_BLOCK];
        #pragma unroll
        for (int j = 0; j < OC_BLOCK; ++j) {
            int oc = oc0 + j;
            acc[j] = (has_bias && oc < Cout) ? bias[oc] : 0.0f;
        }
        int base_z = lz * stride;
        int base_y = ly * stride;
        int base_x = lx * stride;
        for (int c = 0; c < Cg; ++c) {
            for (int kz = 0; kz < K; ++kz) {
                int sz_i = base_z + kz * dilation;
                for (int ky = 0; ky < K; ++ky) {
                    int sy_i = base_y + ky * dilation;
                    int in_row = ((c * sz + sz_i) * sy + sy_i) * sx;
                    int w_c_k = (((c * K + kz) * K + ky) * K);
                    for (int kx = 0; kx < K; ++kx) {
                        int sx_i = base_x + kx * dilation;
                        float v = s_in[in_row + sx_i];
                        int w_off = w_c_k + kx;
                        #pragma unroll
                        for (int j = 0; j < OC_BLOCK; ++j) {
                            acc[j] += v * s_w[j * w_oc_stride + w_off];
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int j = 0; j < OC_BLOCK; ++j) {
            int oc = oc0 + j;
            if (oc < Cout) {
                long long out_idx = (((long long)(n * Cout + oc) * Dout + oz) * Hout + oy) * Wout + ox;
                output[out_idx] = acc[j];
            }
        }
    }
}

__global__ void __launch_bounds__(TILE_X * TILE_Y * TILE_Z) conv3d_fwd_kernel_cout64(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int D, int H, int W,
    int Dout, int Hout, int Wout,
    int z_tiles, int has_bias)
{
    extern __shared__ float smem[];
    float* s_in = smem;
    float* s_w = smem + 3000;
    const int sx = 10;
    const int sy = 10;
    const int sz = 10;
    int xtile = blockIdx.x;
    int ytile = blockIdx.y;
    int zb = blockIdx.z;
    int ztile = zb % z_tiles;
    int zn = zb / z_tiles;
    int oc_half = zn & 1;
    int n = zn >> 1;
    int ox0 = xtile * TILE_X;
    int oy0 = ytile * TILE_Y;
    int oz0 = ztile * TILE_Z;
    int tid = (threadIdx.z * blockDim.y + threadIdx.y) * blockDim.x + threadIdx.x;
    int nthreads = blockDim.x * blockDim.y * blockDim.z;
    for (int i = tid; i < 3000; i += nthreads) {
        int lox = i % sx;
        int t = i / sx;
        int loy = t % sy;
        t /= sy;
        int loz = t % sz;
        int c = t / sz;
        int ix = ox0 + lox;
        int iy = oy0 + loy;
        int iz = oz0 + loz;
        float v = 0.0f;
        if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
            long long in_idx = (((long long)(n * 3 + c) * D + iz) * H + iy) * W + ix;
            v = input[in_idx];
        }
        s_in[i] = v;
    }
    const float4* w4 = reinterpret_cast<const float4*>(weight + (long long)oc_half * 2592);
    for (int i = tid; i < 648; i += nthreads) {
        float4 t = w4[i];
        int idx0 = i * 4;
        #pragma unroll
        for (int u = 0; u < 4; ++u) {
            int idx = idx0 + u;
            int oc = idx / 81;
            int w_off = idx - oc * 81;
            float val = (u == 0) ? t.x : ((u == 1) ? t.y : ((u == 2) ? t.z : t.w));
            s_w[w_off * 32 + oc] = val;
        }
    }
    __syncthreads();
    int lx = threadIdx.x;
    int ly = threadIdx.y;
    int lz = threadIdx.z;
    int ox = ox0 + lx;
    int oy = oy0 + ly;
    if (ox >= Wout || oy >= Hout) return;
    int oz = oz0 + lz;
    const bool valid = (oz < Dout);
    const long long cstride = (long long)Dout * Hout * Wout;
    const long long out_base = (((long long)(n * 64) * Dout + oz) * Hout + oy) * Wout + ox;
    #pragma unroll
    for (int oc_chunk = 0; oc_chunk < 4; ++oc_chunk) {
        float4 acc0, acc1;
        {
            int oc = oc_half * 32 + oc_chunk * 8;
            float b0 = has_bias ? bias[oc + 0] : 0.0f;
            float b1 = has_bias ? bias[oc + 1] : 0.0f;
            float b2 = has_bias ? bias[oc + 2] : 0.0f;
            float b3 = has_bias ? bias[oc + 3] : 0.0f;
            float b4 = has_bias ? bias[oc + 4] : 0.0f;
            float b5 = has_bias ? bias[oc + 5] : 0.0f;
            float b6 = has_bias ? bias[oc + 6] : 0.0f;
            float b7 = has_bias ? bias[oc + 7] : 0.0f;
            acc0 = make_float4(b0, b1, b2, b3);
            acc1 = make_float4(b4, b5, b6, b7);
        }
        #pragma unroll
        for (int c = 0; c < 3; ++c) {
            #pragma unroll
            for (int kz = 0; kz < 3; ++kz) {
                int sz_i = lz + kz;
                #pragma unroll
                for (int ky = 0; ky < 3; ++ky) {
                    int sy_i = ly + ky;
                    int in_row = ((c * sz + sz_i) * sy + sy_i) * sx;
                    int w_c_k = c * 27 + kz * 9 + ky * 3;
                    #pragma unroll
                    for (int kx = 0; kx < 3; ++kx) {
                        float v = s_in[in_row + lx + kx];
                        int w_off = w_c_k + kx;
                        const float4* wptr = reinterpret_cast<const float4*>(s_w + w_off * 32 + oc_chunk * 8);
                        float4 wv0 = wptr[0];
                        float4 wv1 = wptr[1];
                        acc0.x += v * wv0.x;
                        acc0.y += v * wv0.y;
                        acc0.z += v * wv0.z;
                        acc0.w += v * wv0.w;
                        acc1.x += v * wv1.x;
                        acc1.y += v * wv1.y;
                        acc1.z += v * wv1.z;
                        acc1.w += v * wv1.w;
                    }
                }
            }
        }
        if (valid) {
            long long base = out_base + (long long)(oc_half * 32 + oc_chunk * 8) * cstride;
            output[base] = acc0.x;
            output[base + cstride] = acc0.y;
            output[base + 2 * cstride] = acc0.z;
            output[base + 3 * cstride] = acc0.w;
            output[base + 4 * cstride] = acc1.x;
            output[base + 5 * cstride] = acc1.y;
            output[base + 6 * cstride] = acc1.z;
            output[base + 7 * cstride] = acc1.w;
        }
    }
}
at::Tensor conv3d_forward(at::Tensor input, at::Tensor weight, at::Tensor bias,
                          int64_t stride_, int64_t padding_, int64_t dilation_, int64_t groups_) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(input.dim() == 5, "input must be NCDHW");
    TORCH_CHECK(weight.dim() == 5, "weight must be Cout,Cin/groups,K,K,K");

    auto x = input.contiguous();
    auto w = weight.contiguous();

    int64_t N = x.size(0), Cin = x.size(1), D = x.size(2), H = x.size(3), W = x.size(4);
    int64_t Cout = w.size(0), Cg = w.size(1), K = w.size(2);
    int64_t stride = stride_, pad = padding_, dilation = dilation_, groups = groups_;

    TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic");
    TORCH_CHECK(Cin % groups == 0, "in_channels must be divisible by groups");
    TORCH_CHECK(Cout % groups == 0, "out_channels must be divisible by groups");
    TORCH_CHECK(Cg == Cin / groups, "weight input channels mismatch");

    auto out_dim = [&](int64_t in) -> int64_t {
        int64_t num = in + 2 * pad - dilation * (K - 1) - 1;
        return num >= 0 ? (num / stride + 1) : 0;
    };
    int64_t Dout = out_dim(D), Hout = out_dim(H), Wout = out_dim(W);
    TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid output size");

    auto output = at::empty({N, Cout, Dout, Hout, Wout}, x.options());
    if (output.numel() == 0) return output;

    const float* bias_ptr = nullptr;
    int has_bias = 0;
    at::Tensor b;
    if (bias.defined() && bias.numel() == Cout) {
        TORCH_CHECK(bias.is_cuda() && bias.scalar_type() == at::kFloat, "bias must be CUDA float32");
        b = bias.contiguous();
        bias_ptr = b.data_ptr<float>();
        has_bias = 1;
    } else {
        TORCH_CHECK(!bias.defined() || bias.numel() == 0, "bias has wrong shape");
    }

    int x_tiles = (int)((Wout + TILE_X - 1) / TILE_X);
    int y_tiles = (int)((Hout + TILE_Y - 1) / TILE_Y);
    int z_tiles = (int)((Dout + TILE_Z - 1) / TILE_Z);
    int oc_blocks = (int)((Cout + OC_BLOCK - 1) / OC_BLOCK);
    int64_t ocpg = Cout / groups;

    int sx = (TILE_X - 1) * (int)stride + (int)(K - 1) * (int)dilation + 1;
    int sy = (TILE_Y - 1) * (int)stride + (int)(K - 1) * (int)dilation + 1;
    int sz = (TILE_Z - 1) * (int)stride + (int)(K - 1) * (int)dilation + 1;
    int64_t in_sh_elems64 = Cg * (int64_t)sz * sy * sx;
    int64_t w_sh_elems64 = (int64_t)OC_BLOCK * Cg * K * K * K;
    int64_t sh_bytes64 = (in_sh_elems64 + w_sh_elems64) * sizeof(float);

    size_t max_shmem = 48 * 1024;
    auto prop = at::cuda::getCurrentDeviceProperties();
    if (prop != nullptr) max_shmem = std::min<size_t>(max_shmem, prop->sharedMemPerBlock);

    int64_t grid_z64 = N * (int64_t)oc_blocks * z_tiles;
    bool tiled_ok =
        Cout % OC_BLOCK == 0 &&
        ocpg % OC_BLOCK == 0 &&
        sh_bytes64 > 0 && sh_bytes64 <= (int64_t)max_shmem &&
        grid_z64 <= 65535 && x_tiles <= 2147483647 && y_tiles <= 65535 &&
        in_sh_elems64 <= INT32_MAX && w_sh_elems64 <= INT32_MAX;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    long long total_outputs = (long long)output.numel();

    size_t fast_shmem = (size_t)(3000 + 2592) * sizeof(float);
    long long fast_grid_z = (long long)N * z_tiles * 2;
    bool fast_cout64 =
        groups == 1 && Cin == 3 && Cout == 64 && K == 3 &&
        stride == 1 && pad == 0 && dilation == 1 &&
        fast_shmem <= max_shmem &&
        fast_grid_z <= 65535 && x_tiles <= 2147483647 && y_tiles <= 65535;
    if (fast_cout64) {
        dim3 fblock(TILE_X, TILE_Y, TILE_Z);
        dim3 fgrid((unsigned)x_tiles, (unsigned)y_tiles, (unsigned)fast_grid_z);
        conv3d_fwd_kernel_cout64<<<fgrid, fblock, fast_shmem, stream>>>(
            x.data_ptr<float>(), w.data_ptr<float>(), bias_ptr, output.data_ptr<float>(),
            (int)D, (int)H, (int)W, (int)Dout, (int)Hout, (int)Wout,
            z_tiles, has_bias);
        C10_CUDA_KERNEL_LAUNCH_CHECK();
        return output;
    }
    if (tiled_ok) {
        dim3 block(TILE_X, TILE_Y, OC_LANES);
        dim3 grid((unsigned)x_tiles, (unsigned)y_tiles, (unsigned)grid_z64);
        size_t shmem = (size_t)sh_bytes64;
        conv3d_fwd_kernel<<<grid, block, shmem, stream>>>(
            x.data_ptr<float>(), w.data_ptr<float>(), bias_ptr, output.data_ptr<float>(),
            (int)N, (int)Cin, (int)D, (int)H, (int)W,
            (int)Cout, (int)K, (int)Dout, (int)Hout, (int)Wout,
            (int)stride, (int)pad, (int)dilation, (int)groups,
            has_bias, 1, (int)in_sh_elems64, (int)w_sh_elems64,
            x_tiles, y_tiles, z_tiles, oc_blocks, total_outputs);
    } else {
        dim3 block(DIRECT_THREADS);
        long long blocks = (total_outputs + DIRECT_THREADS - 1) / DIRECT_THREADS;
        TORCH_CHECK(blocks <= INT32_MAX, "too many outputs");
        dim3 grid((unsigned)blocks);
        conv3d_fwd_kernel<<<grid, block, 0, stream>>>(
            x.data_ptr<float>(), w.data_ptr<float>(), bias_ptr, output.data_ptr<float>(),
            (int)N, (int)Cin, (int)D, (int)H, (int)W,
            (int)Cout, (int)K, (int)Dout, (int)Hout, (int)Wout,
            (int)stride, (int)pad, (int)dilation, (int)groups,
            has_bias, 0, 0, 0,
            0, 0, 0, 0, total_outputs);
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""

_conv3d_ext = load_inline(
    name="custom_conv3d_single_kernel",
    cpp_sources=CPP_SRC,
    cuda_sources=CUDA_SRC,
    functions=["conv3d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        k = _triple(kernel_size)
        s = _triple(stride)
        p = _triple(padding)
        d = _triple(dilation)
        if not (k[0] == k[1] == k[2] and s[0] == s[1] == s[2] and
                p[0] == p[1] == p[2] and d[0] == d[1] == d[2]):
            raise ValueError("ModelNew expects isotropic kernel/stride/padding/dilation")
        if in_channels % groups != 0 or out_channels % groups != 0:
            raise ValueError("channels must be divisible by groups")

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = k[0]
        self.stride = s[0]
        self.padding = p[0]
        self.dilation = d[0]
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            out_channels, in_channels // groups,
            self.kernel_size, self.kernel_size, self.kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size ** 3
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.bias if self.bias is not None else torch.empty(
            0, device=self.weight.device, dtype=self.weight.dtype)
        return _conv3d_ext.conv3d_forward(
            x, self.weight, bias, self.stride, self.padding, self.dilation, self.groups)

