class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        k = _triple(kernel_size)
        s = _triple(stride)
        p = _triple(padding)
        d = _triple(dilation)
        if not (k[0] == k[1] == k[2] and s[0] == s[1] == s[2] and
                p[0] == p[1] == p[2] and d[0] == d[1] == d[2]):
            raise ValueError("ModelNew expects isotropic kernel/stride/padding/dilation")
        if in_channels % groups != 0 or out_channels % groups != 0:
            raise ValueError("channels must be divisible by groups")

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = k[0]
        self.stride = s[0]
        self.padding = p[0]
        self.dilation = d[0]
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            out_channels, in_channels // groups,
            self.kernel_size, self.kernel_size, self.kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size ** 3
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.bias if self.bias is not None else torch.empty(
            0, device=self.weight.device, dtype=self.weight.dtype)
        return _conv3d_ext.conv3d_forward(
            x, self.weight, bias, self.stride, self.padding, self.dilation, self.groups)

